<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import type {FormInstance,FormProps} from 'ant-design-vue';
import {submitForm,api,matches,pagination,showError,useActions,type Row} from './api';import PagePanel from './PagePanel.vue';import AppIcon from './AppIcon.vue';
const rows=ref<Row[]>([]),loading=ref(false),error=ref(''),search=ref(''),status=ref('all'),createOpen=ref(false),createRef=ref<FormInstance>(),newPolicy=ref({code:'',name:''}),selected=ref<Row|null>(null),versions=ref<Row[]>([]),versionsLoading=ref(false),ruleRef=ref<FormInstance>(),simulationRef=ref<FormInstance>(),simulationOpen=ref(false),simulationResult=ref<Row|null>(null);
const freshRule=()=>({decision:'DENY',priority:100,table:'',environment:'PROD',operation:'SELECT'}),rule=ref(freshRule()),simulation=ref({table:'',environment:'PROD',operation:'SELECT'});const {busy,perform}=useActions();
const labels:Record<string,string>={DRAFT:'草稿',ACTIVE:'已发布',DISABLED:'已停用',DENY:'拒绝',REQUIRE_APPROVAL:'需审批',DEV:'开发',TEST:'测试',STAGING:'预发布',PROD:'生产'};
const filtered=computed(()=>rows.value.filter(row=>matches(row,search.value,['name','code'])&&(status.value==='all'||row.status===status.value)));
const scopeRules:FormProps['rules']={table:[{required:true,message:'请输入数据表名'},{pattern:/^(\*|[a-z][a-z0-9_]{0,254})$/,message:'使用小写表名，或填写 * 匹配所有表'}],environment:[{required:true,message:'请选择环境'}],operation:[{required:true,message:'请选择操作'}]};
async function refresh(){loading.value=true;error.value='';try{rows.value=await api('/api/sql-policies')}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
function openCreate(){newPolicy.value={code:'',name:''};createOpen.value=true}
async function create(){if(await perform('/api/sql-policies',newPolicy.value,'POST','策略草稿已创建')){createOpen.value=false;await refresh()}}
async function openVersions(row:Row){selected.value=row;rule.value=freshRule();versionsLoading.value=true;try{versions.value=await api('/api/sql-policies/'+row.id+'/versions')}catch(e){showError(e)}finally{versionsLoading.value=false}}
async function saveRule(){if(!selected.value)return;const id=selected.value.id;if(await perform('/api/sql-policies/'+id+'/versions',rule.value,'POST','规则版本已保存')){await refresh();const updated=rows.value.find(row=>row.id===id);if(updated)await openVersions(updated)}}
async function publish(row:Row){if(await perform('/api/sql-policies/'+row.id+'/publish',{expectedVersion:row.version},'POST','拒绝规则配置已发布')){await refresh();selected.value=null}}
async function disable(row:Row){if(await perform('/api/sql-policies/'+row.id+'/disable',{expectedVersion:row.version},'POST','策略配置已停用'))await refresh()}
function openSimulation(){simulation.value={table:rule.value.table,environment:rule.value.environment,operation:rule.value.operation};simulationResult.value=null;simulationOpen.value=true}
async function simulate(){if(!selected.value)return;simulationResult.value=await perform('/api/sql-policies/'+selected.value.id+'/simulate',simulation.value,'POST','')}
onMounted(refresh);defineExpose({refresh});
</script>
<template>
 <a-alert v-if="error" :message="error" type="error" show-icon class="dg-notice"/><div class="dg-summary"><div><span>策略总数</span><strong>{{rows.length}}</strong></div><div><span>已发布配置</span><strong>{{rows.filter(r=>r.status==='ACTIVE').length}}</strong></div><div><span>草稿</span><strong>{{rows.filter(r=>r.status==='DRAFT').length}}</strong></div><div><span>已停用</span><strong>{{rows.filter(r=>r.status==='DISABLED').length}}</strong></div></div>
 <a-alert class="dg-notice" type="warning" show-icon message="当前规则用于配置与模拟，尚不参与实际读取判定。"/>
 <PagePanel title="SQL 安全策略"><template #actions><a-button type="primary" @click="openCreate"><AppIcon name="plus"/>新建策略</a-button></template><template #filters><a-input v-model:value="search" allow-clear class="dg-search" placeholder="搜索策略名称或编码" aria-label="搜索策略"><template #prefix><AppIcon name="search"/></template></a-input><a-select v-model:value="status" class="dg-select" aria-label="策略状态" :options="[{value:'all',label:'全部状态'},...['DRAFT','ACTIVE','DISABLED'].map(value=>({value,label:labels[value]}))]"/></template><a-table :data-source="filtered" row-key="id" :loading="loading" :pagination="pagination" :scroll="{x:840}"><a-table-column title="策略" :width="280"><template #default="{record}"><div class="dg-name-cell"><span class="dg-resource-icon"><AppIcon name="policies"/></span><div><strong>{{record.name}}</strong><small>{{record.code}}</small></div></div></template></a-table-column><a-table-column title="最新版本"><template #default="{record}">{{record.latestVersion?'v'+record.latestVersion:'—'}}</template></a-table-column><a-table-column title="最新判定"><template #default="{record}">{{labels[record.latestDecision]||'—'}}</template></a-table-column><a-table-column title="配置状态"><template #default="{record}"><span class="dg-status" :class="record.status==='ACTIVE'?'good':'off'">{{labels[record.status]}}</span></template></a-table-column><a-table-column title="操作" align="right" :width="250"><template #default="{record}"><div class="dg-row-actions"><a-button type="link" @click="openVersions(record)">规则版本</a-button><a-button v-if="record.status==='DRAFT'&&record.latestDecision==='DENY'" type="link" :disabled="busy" @click="publish(record)">发布配置</a-button><a-popconfirm v-if="record.status==='ACTIVE'" title="确认停用此策略配置？" ok-text="停用" cancel-text="取消" @confirm="disable(record)"><a-button type="link" class="dg-muted-action">停用</a-button></a-popconfirm></div></template></a-table-column></a-table></PagePanel>
 <a-modal v-model:open="createOpen" title="新建策略草稿" centered ok-text="创建" cancel-text="取消" :confirm-loading="busy" @ok="submitForm(createRef,create)"><a-form ref="createRef" :model="newPolicy" layout="vertical" @finish="create"><a-form-item label="策略名称" name="name" :rules="[{required:true,whitespace:true,message:'请输入名称'},{max:200,message:'名称过长'}]"><a-input v-model:value="newPolicy.name"/></a-form-item><a-form-item label="策略编码" name="code" :rules="[{required:true,message:'请输入编码'},{pattern:/^[a-z][a-z0-9_-]{2,119}$/,message:'3 到 120 位小写字母、数字、下划线或短横线，须以字母开头'}]"><a-input v-model:value="newPolicy.code" placeholder="例如 deny-sensitive-read"/></a-form-item></a-form></a-modal>
 <a-modal :open="!!selected" :title="(selected?.name||'策略')+' 的规则版本'" centered :width="820" :footer="null" @cancel="selected=null"><template v-if="selected"><a-form v-if="selected.status==='DRAFT'" ref="ruleRef" :model="rule" :rules="scopeRules" layout="vertical" @finish="saveRule"><div class="dg-form-grid dg-form-grid-three"><a-form-item label="判定"><a-select v-model:value="rule.decision" :options="['DENY','REQUIRE_APPROVAL'].map(value=>({value,label:labels[value]}))"/></a-form-item><a-form-item label="优先级"><a-input-number v-model:value="rule.priority" :min="1" :max="10000"/></a-form-item><a-form-item label="数据表" name="table"><a-input v-model:value="rule.table" placeholder="表名或 *"/></a-form-item><a-form-item label="环境" name="environment"><a-select v-model:value="rule.environment" :options="['DEV','TEST','STAGING','PROD'].map(value=>({value,label:labels[value]}))"/></a-form-item><a-form-item label="操作" name="operation"><a-select v-model:value="rule.operation" :options="['SELECT','INSERT','UPDATE','DELETE'].map(value=>({value,label:value}))"/></a-form-item></div><div class="dg-inline-actions"><a-button type="primary" html-type="submit" :loading="busy">保存新版本</a-button><a-button @click="openSimulation">模拟匹配</a-button></div></a-form><div v-else class="dg-inline-actions"><a-button @click="openSimulation">模拟匹配</a-button></div><a-table :data-source="versions" :loading="versionsLoading" row-key="revision" :pagination="{pageSize:5}" :scroll="{x:680}"><a-table-column title="版本" data-index="revision"/><a-table-column title="判定"><template #default="{record}">{{labels[record.decision]}}</template></a-table-column><a-table-column title="优先级" data-index="priority"/><a-table-column title="数据表" data-index="tableName"/><a-table-column title="环境"><template #default="{record}">{{labels[record.environment]}}</template></a-table-column><a-table-column title="操作" data-index="operation"/><a-table-column title="配置发布"><template #default="{record}">{{record.published?'已发布':'未发布'}}</template></a-table-column></a-table></template></a-modal>
 <a-modal v-model:open="simulationOpen" title="策略模拟" centered ok-text="模拟" cancel-text="关闭" :confirm-loading="busy" @ok="submitForm(simulationRef,simulate)"><a-form ref="simulationRef" :model="simulation" :rules="scopeRules" layout="vertical" @finish="simulate"><a-form-item label="数据表" name="table"><a-input v-model:value="simulation.table"/></a-form-item><div class="dg-form-grid"><a-form-item label="环境" name="environment"><a-select v-model:value="simulation.environment" :options="['DEV','TEST','STAGING','PROD'].map(value=>({value,label:labels[value]}))"/></a-form-item><a-form-item label="操作" name="operation"><a-select v-model:value="simulation.operation" :options="['SELECT','INSERT','UPDATE','DELETE'].map(value=>({value,label:value}))"/></a-form-item></div></a-form><a-alert v-if="simulationResult" :type="simulationResult.matched?'info':'warning'" show-icon :message="(simulationResult.matched?'匹配规则':'未匹配规则')+'，模拟判定：'+labels[simulationResult.decision]"/></a-modal>
</template>
